select 
from sys_user

    del_flag = '0'

        and user_name like concat('%', #{userName}, '%')


        and nick_name like concat('%', #{nickName}, '%')


        and phonenumber like concat('%', #{phonenumber}, '%')


        and status = #{status}


        and dept_id = #{deptId}


        and create_time  >=  #{beginTime}


        and create_time  <=  #{endTime}


order by create_time

